# Purpose: tests that the agent's web access stays as decided (ds.ai.web): page fetch only, no
#          search; deferred and capped; and the docs-first rule always in the instructions.
# Usage: uv run pytest tests/ds/ai/test_web_capability.py
# ---------------------------------------------------------------------------
from __future__ import annotations

from ds.ai import web
from ds.ai.agent import agent
from pydantic_ai.capabilities import WebFetch, WebSearch


def _capabilities() -> list[object]:
    return list(agent._root_capability.capabilities)


def test_agent_can_fetch_pages_but_not_search():
    caps = _capabilities()
    assert web.web_capability in caps
    assert not any(isinstance(cap, WebSearch) for cap in caps)


def test_fetch_is_deferred_capped_and_native_only():
    cap = web.web_capability
    assert isinstance(cap, WebFetch)
    assert cap.defer_loading
    assert cap.max_uses == web.MAX_FETCHES
    assert cap.max_content_tokens == web.MAX_PAGE_TOKENS
    # no local fallback: a local fetch would bypass ds.util.http
    assert not cap.local


def test_docs_first_rule_is_always_on():
    instructions = [getattr(item, "instruction", item) for item in agent._instructions]
    assert web.WEB_RULE in instructions
    assert "docs" in web.WEB_RULE
    assert "from the web: <url>" in web.WEB_RULE
